size_t pqcp_channel_policy_conformance_catalog_count(void)
{
	return ARRAY_SIZE(channel_policy_catalog);
}

int pqcp_channel_policy_conformance_catalog_get(
	size_t index,
	struct pqcp_operation_conformance_case *test_case)
{
	if (index >= ARRAY_SIZE(channel_policy_catalog) ||
	    test_case == NULL) {
		return -EINVAL;
	}
	*test_case = channel_policy_catalog[index];
	test_case->schema_version =
		PQCP_OPERATION_CONFORMANCE_SCHEMA_VERSION;
	test_case->domain = PQCP_OPERATION_CONFORMANCE_CHANNEL_POLICY;
	test_case->case_id =
		PQCP_OPERATION_CONFORMANCE_CASE_ID(
			test_case->domain,
			test_case->condition,
			test_case->operation);
	return 0;
}

int pqcp_channel_policy_conformance_catalog_audit(void)
{
	if (ARRAY_SIZE(channel_policy_catalog) !=
	    PQCP_OPERATION_CONFORMANCE_CASES_PER_DOMAIN) {
		return -EBADMSG;
	}
	for (size_t index = 0U;
	     index < ARRAY_SIZE(channel_policy_catalog);
	     ++index) {
		struct pqcp_operation_conformance_case test_case_value;
		const struct pqcp_operation_conformance_case *test_case =
			&test_case_value;
		struct pqcp_channel_policy_decision actual;
		int ret;

		ret = pqcp_channel_policy_conformance_catalog_get(
			index, &test_case_value);
		if (ret != 0) {
			return ret;
		}
		if (test_case->schema_version !=
			    PQCP_OPERATION_CONFORMANCE_SCHEMA_VERSION ||
		    test_case->domain != PQCP_OPERATION_CONFORMANCE_CHANNEL_POLICY ||
		    test_case->case_id !=
			    PQCP_OPERATION_CONFORMANCE_CASE_ID(
				test_case->domain,
				test_case->condition,
				test_case->operation)) {
			return -EBADMSG;
		}
		ret = pqcp_channel_policy_lookup(
			(enum pqcp_channel_policy_state)test_case->condition,
			(enum pqcp_channel_control_kind)test_case->operation,
			&actual);
		if (ret != 0) {
			return ret;
		}
		if (
		    actual.action != test_case->decision ||
		    actual.next_state != test_case->next_state ||
		    actual.flags != test_case->reason_mask ||
		    actual.error != test_case->expected_error) {
			return -EBADMSG;
		}
	}
	return 0;
}
